svg.script:
(function(){
  var s = document.getElementById('scene-near-arrival');
  if (!s || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  var play = function(){ s.classList.add('play'); };
  if ('IntersectionObserver' in window){
    var io = new IntersectionObserver(function(es){
      es.forEach(function(e){ if (e.isIntersecting){ play(); io.disconnect(); } });
    }, {threshold:.3});
    io.observe(s);
  } else { play(); }
})();
